/* car_sprites.js —— JZH高速：原创 3D 斜前方渲染的小车图标（商店/车库/选车共用）。\n   window.carSprite(id) 返回一段 <img> HTML，直接塞 innerHTML 即可。全部原创造型。*/
(function(){
  var IMG={"v1":"data:image/png;base64,","v2":"data:image/png;base64,","v3":"data:image/png;base64,","v4":"data:image/png;base64,","v5":"data:image/png;base64,"};
  window.CAR_IMG=IMG;
  window.carSprite=function(id){ var u=IMG[id]; return u? ('<img src="'+u+'" alt="" style="width:100%;height:100%;object-fit:contain;display:block">') : ''; };
})();
